      const provider = this.getProvider(network);
      const contract = new ethers.Contract(contractAddress, ERC1155_ABI, provider);

      // Get metadata URI
      const uri = await contract.uri(tokenId);

      // Fetch metadata from IPFS
      if (uri.startsWith("ipfs://")) {
        const cid = uri.replace("ipfs://", "");
        const gateway = process.env.IPFS_GATEWAY || "https://ipfs.io";
        const metadataUrl = `${gateway}/ipfs/${cid}`;

        const response = await fetch(metadataUrl);
        const metadata = await response.json();

        return {
          contractAddress,
          tokenId,
          network,
          uri,
          metadata
        };
      }

      return { contractAddress, tokenId, network, uri };

    } catch (error: any) {
      throw new Error(`Failed to get video NFT: ${error.message}`);
    }
  }

  /**
   * Create complete release package (audio + video NFTs)
   */
  async createReleasePackage(params: {
    songId: string;
    audioPath: string;
    videoPath: string;
    title: string;
    artist: string;
    network: string;
    walletId: string;
  }): Promise<{
    audioNFT: any;
    videoNFT: VideoNFTResult;
  }> {
    // Mint video NFT
    const videoNFT = await this.mintVideoNFT({
      videoPath: params.videoPath,
      title: params.title,
      artist: params.artist,
      network: params.network,
      walletId: params.walletId
    });

    // Mint audio NFT using existing service
    const audioNFT = await jesusCartelService.mintSongNFT({
      songId: params.songId,
      title: params.title,
      artist: params.artist,
      audioFile: params.audioPath,
      network: params.network,
      walletId: params.walletId
    });

    return { audioNFT, videoNFT };
  }
}

// Singleton instance
export const videoNFTService = new VideoNFTService();

// Export types
export type {
  VideoNFTMetadata,
  MintVideoNFTParams,
  VideoNFTResult
};

